// Issue-#163 C0 — main-thread (lepus) program for the `octane-mts-block` cell.
//
// The runtime half of the spike. Its create functions are *not* here: they are
// generated by `emit.mjs` from the program `derive.mjs` lowers out of
// `app/src/App.lynx.tsrx`, and spliced in by `build.mjs` at the marker below.
//
// Everything below the splice is `prototype/lepus-root.js`'s runtime half,
// carried over deliberately rather than rewritten. C0 asks one question — does
// a main-thread program that came from the compiler's own lowering land where a
// hand-written one lands — and the only way that question has an answer is if
// the mount ladder, the slot-delta applier, the event tokens, the counters and
// the engine entry points are the same code. The generated create functions are
// the single variable.
//
// Two differences from `octane-direct`, both consequences of emitting from a
// program rather than writing for a fixture, both stated because they are the
// spike's own overhead rather than the architecture's:
//
//   * The program declares three value slots per row (class, id text, label
//     text); the hand-written cell keeps two, having noticed that the id text
//     is written once and never addressed again. So this cell performs one
//     extra `push` per row on the first screen, and maintains one extra array
//     on remove and swap. Dropping write-once slots is a real C1 optimization,
//     and leaving it out of C0 keeps the derived cell honest rather than
//     flattering.
//   * A row's values arrive through a one-call adapter (`createRowFor`), which
//     is the work a compiled component body would do: it is what turns
//     `(id, label, selected)` into the program's slot order.

/* global __CreatePage, __CreateView, __CreateText, __CreateRawText, __AppendElement,
   __InsertElementBefore, __RemoveElement, __SetClasses, __SetAttribute, __SetID, __AddEvent,
   __GetElementUniqueID, __SetCSSId, __FlushElementTree */

(function () {
	'use strict';

	// __AUTO_ROWS__ is replaced by build.mjs (mount-create FCP ladder variant).
	var AUTO_ROWS = __AUTO_ROWS__;

	var OP_RUN_ROWS = 1;
	var OP_CLEAR = 2;
	var OP_SET_LABEL = 3;
	var OP_SELECT = 4;
	var OP_REMOVE = 5;
	var OP_SWAP = 6;

	var page = null;
	var pageId = 0;
	var rowsParent = null;
	var selectedIndex = -1;

	// @GENERATED@

	// The slot table under the names the applier below uses. `rowSlot1` is the
	// id raw text: retained because the program declares it, never written.
	var rowViews = rowSlot0;
	var labelRaws = rowSlot2;

	// What a compiled component body does: put this row's values in the program's
	// slot order, and derive its event tokens from its identity so an instance
	// never re-registers a listener.
	function createRowFor(id, label, selected) {
		createRow(selected ? 'row danger' : 'row', String(id), label, 's:' + id, 'r:' + id);
	}

	// -- deterministic mount ladder (mirrors app/src/data.ts buildDataSeeded) --
	var ADJECTIVES = [
		'pretty',
		'large',
		'big',
		'small',
		'tall',
		'short',
		'long',
		'handsome',
		'plain',
		'quaint',
		'clean',
		'elegant',
		'easy',
		'angry',
		'crazy',
		'helpful',
		'mushy',
		'odd',
		'unsightly',
		'adorable',
		'important',
		'inexpensive',
		'cheap',
		'expensive',
		'fancy',
	];
	var COLOURS = [
		'red',
		'yellow',
		'blue',
		'green',
		'pink',
		'brown',
		'purple',
		'brown',
		'white',
		'black',
		'orange',
	];
	var NOUNS = [
		'table',
		'chair',
		'house',
		'bbq',
		'desk',
		'car',
		'pony',
		'cookie',
		'sandwich',
		'burger',
		'pizza',
		'mouse',
		'keyboard',
	];

	function mountSeededRows(count) {
		for (var i = 0; i < count; i++) {
			createRowFor(
				i + 1,
				ADJECTIVES[i % 25] + ' ' + COLOURS[(i * 7) % 11] + ' ' + NOUNS[(i * 13) % 13],
				false,
			);
		}
	}

	// -- floor counters --------------------------------------------------------
	//
	// The architecture floor's answer to `reconcileChildren` visits (issue #103
	// U0). `rowVisits` is how many row regions a patch touches; `writes` is how
	// many PAPI slot writes it performs. Both are deterministic for a given
	// operation, which is what makes them comparable with the octane cell's
	// blueprint count rather than with a wall clock.
	//
	// Unconditional rather than build-flagged: a patch performs O(change)
	// increments, so `select` pays two integer adds against tens of
	// milliseconds. The measured cell and the counted cell are the same bundle.
	var floorCounters = { rowVisits: 0, writes: 0 };
	globalThis.__BENCH_DIRECT_MAIN__ = floorCounters;

	// -- slot-delta applier: table dispatch into pre-bound PAPI writes ---------
	function applyDelta(ops) {
		var i = 0;
		var n = ops.length;
		while (i < n) {
			var op = ops[i++];
			if (op === OP_RUN_ROWS) {
				var count = ops[i++];
				floorCounters.rowVisits += count;
				floorCounters.writes += count * 2;
				for (var k = 0; k < count; k++) {
					createRowFor(ops[i], ops[i + 1], false);
					i += 2;
				}
			} else if (op === OP_CLEAR) {
				floorCounters.rowVisits += rowViews.length;
				for (var c = rowViews.length - 1; c >= 0; c--) __RemoveElement(rowsParent, rowViews[c]);
				rowViews.length = 0;
				rowSlot1.length = 0;
				labelRaws.length = 0;
				selectedIndex = -1;
			} else if (op === OP_SET_LABEL) {
				var index = ops[i++];
				floorCounters.rowVisits += 1;
				floorCounters.writes += 1;
				__SetAttribute(labelRaws[index], 'text', ops[i++]);
			} else if (op === OP_SELECT) {
				var prev = ops[i++];
				var next = ops[i++];
				var touched = (prev === -1 ? 0 : 1) + (next === -1 ? 0 : 1);
				floorCounters.rowVisits += touched;
				floorCounters.writes += touched;
				if (prev !== -1) __SetClasses(rowViews[prev], 'row');
				if (next !== -1) __SetClasses(rowViews[next], 'row danger');
				selectedIndex = next;
			} else if (op === OP_REMOVE) {
				var at = ops[i++];
				floorCounters.rowVisits += 1;
				__RemoveElement(rowsParent, rowViews[at]);
				rowViews.splice(at, 1);
				rowSlot1.splice(at, 1);
				labelRaws.splice(at, 1);
				if (selectedIndex === at) selectedIndex = -1;
				else if (selectedIndex > at) selectedIndex -= 1;
			} else if (op === OP_SWAP) {
				var a = ops[i++];
				var b = ops[i++];
				floorCounters.rowVisits += 2;
				var rowA = rowViews[a];
				var rowB = rowViews[b];
				var afterB = b + 1 < rowViews.length ? rowViews[b + 1] : null;
				__InsertElementBefore(rowsParent, rowB, rowA);
				if (afterB) __InsertElementBefore(rowsParent, rowA, afterB);
				else __AppendElement(rowsParent, rowA);
				rowViews[a] = rowB;
				rowViews[b] = rowA;
				var labelA = labelRaws[a];
				labelRaws[a] = labelRaws[b];
				labelRaws[b] = labelA;
				var idA = rowSlot1[a];
				rowSlot1[a] = rowSlot1[b];
				rowSlot1[b] = idA;
				if (selectedIndex === a) selectedIndex = b;
				else if (selectedIndex === b) selectedIndex = a;
			} else {
				throw new Error('octane-mts-block: unknown delta op ' + op);
			}
		}
		__FlushElementTree(page);
	}

	// -- engine entry points ---------------------------------------------------
	globalThis.processData = function (data) {
		return data != null ? data : {};
	};
	globalThis.renderPage = function () {
		createChrome();
		if (AUTO_ROWS > 0) mountSeededRows(AUTO_ROWS);
		__FlushElementTree(page);
	};
	globalThis.updatePage = function () {};
	globalThis.updateGlobalProps = function () {};
	// Background → main: the typed slot-delta channel (callLepusMethod target).
	globalThis.octaneDirectPatch = function (message) {
		applyDelta(message.data);
	};
})();
